UPDATE emotion_companion 
SET last_interaction = #{when, typeHandler=com.example.demo.config.SQLiteLocalDateTimeTypeHandler},
    interaction_count = interaction_count + 1,
    updated_at = #{when, typeHandler=com.example.demo.config.SQLiteLocalDateTimeTypeHandler}
WHERE user_id = #{userId}

UPDATE emotion_companion 
SET last_chat = #{when, typeHandler=com.example.demo.config.SQLiteLocalDateTimeTypeHandler},
    chat_count = chat_count + 1,
    updated_at = #{when, typeHandler=com.example.demo.config.SQLiteLocalDateTimeTypeHandler}
WHERE user_id = #{userId}
